const items = $input.all();
const today = new Date();
const warningDays = 15; // Alerta com 15 dias de antecedência para FEFO

const expiringSoon = [];
const expired = [];

for (const item of items) {
  const data = item.json;
  if (data.expiry_date) {
    const expiry = new Date(data.expiry_date);
    const diffTime = expiry - today;
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

    if (diffDays <= 0) {
      expired.push({
        nome: data.part_detail?.name || `Item #${data.part}`,
        lote: data.batch || 'Sem Lote',
        validade: data.expiry_date,
        quantidade: data.quantity,
        localizacao: data.location_detail?.name || 'Não definida',
        status: 'VENCIDO'
      });
    } else if (diffDays <= warningDays) {
      expiringSoon.push({
        nome: data.part_detail?.name || `Item #${data.part}`,
        lote: data.batch || 'Sem Lote',
        validade: data.expiry_date,
        diasRestantes: diffDays,
        quantidade: data.quantity,
        localizacao: data.location_detail?.name || 'Não definida',
        status: 'PRÓXIMO AO VENCIMENTO (FEFO)'
      });
    }
  }
}

return [{
  json: {
    totalExpired: expired.length,
    totalExpiringSoon: expiringSoon.length,
    expiredList: expired,
    expiringList: expiringSoon,
    hasAlerts: (expired.length > 0 || expiringSoon.length > 0)
  }
}];

